use std::fs

fn main() {
    let limit: int = 200000
    let mut sieve: Vec<bool> = [true; 200001]
    let mut counts: Vec<int> = [0; 200001]
    let mut largest: Vec<int> = [0; 200001]
    let mut cnt: int = 0
    let mut last: int = 0
    let mut i: int = 0
    while i <= limit {
        if i >= 2 && sieve[i] {
            cnt += 1
            last = i
            let mut j: int = i * i
            while j <= limit {
                sieve[j] = false
                j += i
            }
        }
        counts[i] = cnt
        largest[i] = last
        i += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if first {
            first = false
            continue
        }
        if t.len() == 0 {
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${counts[n]} ${largest[n]}")
        }
    }
}

